mkdir -p /tmp/bot-check && cat > /tmp/bot-check/check.mjs <<'EOF'
import assert from 'node:assert/strict';
import { checkSms } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-haiku/work/courier-g1-3/bot.mjs';

const ok = { phone: '+13125550142', timeZone: 'America/Chicago', marketingConsent: true, optedOutAt: null };
const mk = (over = {}, to = {}) => ({ kind: 'marketing', body: 'Sale today. Reply STOP to opt out.', to: { ...ok, ...to }, ...over });
const tx = (to = {}) => ({ kind: 'transactional', body: 'Your code is 123456', to: { ...ok, marketingConsent: false, ...to } });
const at = (iso) => new Date(iso);

// Chicago is UTC-5 on 2026-10-22 (CDT). 13:00Z = 08:00 local, 12:59Z = 07:59, 01:59Z(+1d) = 20:59, 02:00Z = 21:00.
assert.deepEqual(checkSms(mk(), at('2026-10-22T13:00:00Z')), { allowed: true, reason: null });
assert.equal(checkSms(mk(), at('2026-10-22T12:59:00Z')).reason, 'quiet_hours');
assert.deepEqual(checkSms(mk(), at('2026-10-23T01:59:00Z')), { allowed: true, reason: null });
assert.equal(checkSms(mk(), at('2026-10-23T02:00:00Z')).reason, 'quiet_hours');
// Server zone must not matter: same instants under a different TZ.
process.env.TZ = 'Asia/Tokyo';
assert.equal(checkSms(mk(), at('2026-10-23T02:00:00Z')).reason, 'quiet_hours');
assert.deepEqual(checkSms(mk(), at('2026-10-22T15:00:00Z')), { allowed: true, reason: null });
process.env.TZ = 'UTC';

assert.equal(checkSms(mk({}, { marketingConsent: false }), at('2026-10-22T15:00:00Z')).reason, 'no_marketing_consent');
assert.equal(checkSms(mk({}, { marketingConsent: 'yes' }), at('2026-10-22T15:00:00Z')).reason, 'no_marketing_consent');
assert.equal(checkSms(mk({}, { optedOutAt: '2026-10-01T00:00:00Z' }), at('2026-10-22T15:00:00Z')).reason, 'opted_out');
assert.equal(checkSms(tx({ optedOutAt: '2026-10-01T00:00:00Z' }), at('2026-10-22T15:00:00Z')).reason, 'opted_out_transactional');
assert.equal(checkSms(mk({ body: 'Sale today!' }), at('2026-10-22T15:00:00Z')).reason, 'missing_opt_out_text');
assert.equal(checkSms(mk({}, { phone: '+10125550142' }), at('2026-10-22T15:00:00Z')).reason, 'invalid_phone_number');
assert.equal(checkSms(mk({}, { phone: '+442071838750' }), at('2026-10-22T15:00:00Z')).reason, 'invalid_phone_number');
assert.equal(checkSms(mk({}, { timeZone: 'Mars/Olympus' }), at('2026-10-22T15:00:00Z')).reason, 'invalid_time_zone');
assert.equal(checkSms(mk(), new Date('nope')).reason, 'invalid_input');
assert.equal(checkSms(mk({ kind: 'promo' }), at('2026-10-22T15:00:00Z')).reason, 'invalid_input');
assert.equal(checkSms(mk({}, { optedOutAt: 'garbage' }), at('2026-10-22T15:00:00Z')).reason, 'invalid_input');

// Transactional: allowed at any hour, without consent.
assert.deepEqual(checkSms(tx(), at('2026-10-22T03:00:00Z')), { allowed: true, reason: null });
assert.deepEqual(checkSms(tx(), at('2026-10-22T15:00:00Z')), { allowed: true, reason: null });

// Every blocking code is distinct.
const codes = ['invalid_input','invalid_phone_number','invalid_time_zone','opted_out','opted_out_transactional','no_marketing_consent','quiet_hours','missing_opt_out_text'];
assert.equal(new Set(codes).size, codes.length);
console.log('all checks passed');
EOF
node /tmp/bot-check/check.mjs && node --check <HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-haiku/work/courier-g1-3/bot.mjs && echo syntax-ok
